export const BODY: string = "\n<p>آپ کو تصویر متن کے طور پر چاہیے: اسٹائل شیٹ کے لیے لوگو، ای میل کے لیے آئیکن یا JSON پے لوڈ کے لیے تصویر۔ مرحلے معلوم ہوں تو تبدیلی میں تقریباً ایک منٹ لگتا ہے۔</p>\n<p>یہ رہنما تصویر کو Base64 میں بدلنا چار مرحلوں میں بتاتا ہے: فائل اپ لوڈ کریں، آؤٹ پٹ فارمیٹ چنیں، اسٹرنگ کاپی یا ڈاؤن لوڈ کریں اور اسے اپنے کوڈ میں پیسٹ کریں۔</p>\n<p>نہ کوئی سافٹ ویئر انسٹال کرنا ہے، نہ اکاؤنٹ بنانا ہے، اور کچھ بھی کہیں اپ لوڈ نہیں ہوتا۔ تصویر شروع سے آخر تک آپ کے براؤزر میں مقامی طور پر انکوڈ ہوتی ہے۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے کیا چاہیے</h2>\n<p>آپ کو تصویر فائل خود چاہیے، PNG، JPG، WebP، GIF، SVG، BMP یا ICO فارمیٹ میں، 15 MB تک۔ لوگو، آئیکن اور چھوٹی تصویریں عام امیدوار ہوتی ہیں۔</p>\n<p>جان لیں کہ اسٹرنگ کہاں جا رہی ہے۔ HTML صفحہ Data URL چاہتا ہے، اسٹائل شیٹ CSS url() قیمت چاہتی ہے اور API عام طور پر بغیر کسی پیش لاحقے کے کچی اسٹرنگ چاہتا ہے۔</p>\n<p>اگر تصویر بڑی ہو تو پہلے اسے چھوٹا کرنے پر غور کریں۔ 2 MB تصویر 2.7 MB اسٹرنگ بن جاتی ہے، جسے کاپی کرنا مشکل اور پڑھنا سست ہوتا ہے، جبکہ کمپریس شدہ نسخہ اس کا دسواں حصہ ہو سکتا ہے۔</p>\n<h2 id=\"step-1-upload-or-paste\">مرحلہ 1: تصویر اپ لوڈ کریں یا اسکرین شاٹ پیسٹ کریں</h2>\n<p><a href=\"/ur/tasveer-ko-base64-mein-convert-karein/\">Image to Base64 کنورٹر</a> کھولیں اور اپنی تصویر اپ لوڈ والے حصے میں گھسیٹ دیں۔ آپ اپنے آلے سے فائل چننے کے لیے اس حصے پر کلک بھی کر سکتے ہیں۔</p>\n<p>اگر تصویر ابھی آپ کی اسکرین پر ہے تو اسے کاپی کریں اور Ctrl+V سے پیسٹ کریں۔ ٹول کلپ بورڈ تصویریں سیدھا قبول کرتا ہے، اس لیے اسکرین شاٹ پہلے فائل محفوظ کیے بغیر انکوڈ ہو سکتا ہے۔</p>\n<p>ٹول فائل پڑھتا ہے اور اس کے ابعاد اور فارمیٹ کے ساتھ پیش نظارہ دکھاتا ہے۔ جانچیں کہ پیش نظارہ وہی تصویر ہے جو آپ چاہتے تھے، کیونکہ آپ جو اسٹرنگ کاپی کریں گے، وہ بالکل یہی فائل ہوگی۔</p>\n<h2 id=\"step-2-choose-output-format\">مرحلہ 2: آؤٹ پٹ فارمیٹ چنیں</h2>\n<p>آؤٹ پٹ والے حصے کے اوپر چار ٹیب ہیں: Data URL، Raw، HTML اور CSS۔ وہ چنیں جو آپ کی اسٹرنگ کی منزل سے میل کھاتا ہو۔</p>\n<p>Data URL اس وقت چنیں جب آپ کو تصویر ماخذ یا اسٹائل شیٹ پس منظر کے لیے مکمل URI چاہیے۔ اس میں میڈیا قسم اور انکوڈنگ نشان شامل ہوتا ہے، اس لیے یہ ہر جگہ کام کرتا ہے جہاں URL کام کرتا ہے۔</p>\n<p>Raw اس وقت چنیں جب آپ تصویر API کو بھیج رہے ہوں یا ڈیٹا بیس میں محفوظ کر رہے ہوں۔ Raw آؤٹ پٹ صرف اسٹرنگ ہوتی ہے، بغیر پیش لاحقے کے، جو وہ شکل ہے جس کی زیادہ تر API توقع کرتی ہیں۔</p>\n<h2 id=\"step-3-copy-or-download\">مرحلہ 3: آؤٹ پٹ کاپی کریں یا ڈاؤن لوڈ کریں</h2>\n<p>اسٹرنگ اپنے کلپ بورڈ پر رکھنے کے لیے Copy Output بٹن پر کلک کریں۔ آئیکن اور لوگو جیسی چھوٹی اسٹرنگ کے لیے یہی کافی ہے۔</p>\n<p>لمبی اسٹرنگ کے لیے کاپی کی بجائے ڈاؤن لوڈ بٹن استعمال کریں۔ کئی میگا بائٹ والی اسٹرنگ کاپی کرنا سست یا ناقابل اعتماد ہو سکتا ہے، جبکہ ڈاؤن لوڈ شدہ متن فائل بغیر کٹوتی کے بالکل آؤٹ پٹ رکھتی ہے۔</p>\n<p>اگر آپ کا براؤزر کلپ بورڈ رسائی روک دے تو ٹول بتا دے گا۔ صفحے کے لیے کلپ بورڈ اجازت دیں، یا ڈاؤن لوڈ بٹن کو متبادل کے طور پر استعمال کریں جسے کسی اجازت کی ضرورت نہیں ہوتی۔</p>\n<h2 id=\"step-4-paste-into-code\">مرحلہ 4: اسٹرنگ اپنے کوڈ میں پیسٹ کریں</h2>\n<p>آؤٹ پٹ وہاں پیسٹ کریں جہاں اسے ہونا چاہیے: Data URL تصویر ماخذ یا اسٹائل شیٹ میں، کچی اسٹرنگ JSON خانے میں، HTML ٹکڑا صفحے میں یا CSS قیمت پس منظر خاصیت میں۔</p>\n<p>نتیجہ فوراً آزمائیں۔ صفحہ کھولیں، آزمائشی ای میل بھیجیں یا API کال کریں، اور یقین کریں کہ تصویر دکھائی دیتی ہے۔ غلط خانے میں پیسٹ شدہ اسٹرنگ خاموشی سے ناکام ہوگی یا ٹوٹی تصویر دکھائے گی۔</p>\n<p>اصل تصویر فائل رکھیں۔ اگر ایمبیڈ شدہ نسخہ کبھی بدلنا ہو تو آپ اسٹرنگ ڈی کوڈ کر کے دوبارہ انکوڈ کرنے کی بجائے اصل سے دوبارہ انکوڈ کریں گے۔</p>\n<h2 id=\"encoding-an-svg-logo\">SVG لوگو انکوڈ کرنا</h2>\n<p>SVG لوگو صاف انکوڈ ہوتے ہیں کیونکہ وہ پہلے سے متن ہوتے ہیں۔ SVG فائل اپ لوڈ کریں اور ٹول Base64 اسٹرنگ بناتا ہے جو واپس ڈی کوڈ ہو کر وہی ویکٹر گرافک بنتی ہے۔</p>\n<p>SVG کے لیے Data URL data:image/svg+xml;base64 سے شروع ہوتا ہے، اس کے بعد اسٹرنگ آتی ہے۔ اسے تصویر ماخذ میں پیسٹ کریں اور لوگو کسی بھی سائز پر تیز رینڈر ہوتا ہے۔</p>\n<p>سائز پر نظر رکھیں، البتہ۔ کئی راستوں والا پیچیدہ SVG بڑا ہو سکتا ہے، اور اس کی Base64 شکل ایک تہائی اور بڑی ہوتی ہے۔ سادہ لوگو ٹھیک ہے، تفصیلی مثال فائل کے طور پر لنک کرنا بہتر ہو سکتا ہے۔</p>\n<h2 id=\"encoding-a-favicon\">فیویکن انکوڈ کرنا</h2>\n<p>فیویکن ICO فائلیں کنورٹر میں کسی بھی دوسرے فارمیٹ کی طرح کام کرتی ہیں۔ .ico فائل اپ لوڈ کریں اور ایک فائل والے صفحے یا ای میل ٹیمپلیٹ میں استعمال کے لیے Data URL کاپی کریں۔</p>\n<p>زیادہ تر سائٹس کو فیویکن فائل کے طور پر لنک کرنا چاہیے، ایمبیڈ کرنے کی بجائے۔ لنک شدہ فیویکن براؤزر کیش کرتا ہے، جبکہ ایمبیڈ شدہ ہر صفحے کے ساتھ ڈاؤن لوڈ ہوتا ہے جس میں وہ ہو۔</p>\n<p>ایمبیڈ کرنا ایک فائل والے صفحوں، آف لائن دستاویزات اور ای میل ٹیمپلیٹ کے لیے معنی رکھتا ہے، جہاں کوئی الگ فائل نہیں لی جا سکتی۔ ان سیاق میں ایمبیڈ شدہ آئیکن ہی واحد طریقہ ہے جس سے فیویکن دکھائی دیتا ہے۔</p>\n<h2 id=\"encoding-for-html-email\">HTML ای میل کے لیے تصویریں انکوڈ کرنا</h2>\n<p>HTML ای میل بیرونی تصویر فائلوں پر بھروسا نہیں کر سکتیں، کیونکہ کئی کلائنٹ پہلے سے طے شدہ طور پر دور دراز تصویریں روک دیتے ہیں۔ تصویر کو Data URL کے طور پر ایمبیڈ کرنے سے وہ فوراً دکھائی دیتی ہے، آف لائن بھی۔</p>\n<p>ایمبیڈ شدہ ای میل تصویریں چھوٹی رکھیں۔ لوگو یا چھوٹا بینر اچھا کام کرتا ہے، مگر بڑی تصویر پیغام کو بھاری اور فون پر کھلنے میں سست بنا دیتی ہے۔</p>\n<p>بھیجنے سے پہلے آزمائیں۔ کچھ ای میل کلائنٹ ان لائن Base64 تصویریں روک دیتے ہیں، اور آپ کا پیغام ان قارئین کے لیے ٹوٹی تصویروں کے ساتھ پہنچ سکتا ہے۔ اپنے سامعین کے استعمال کردہ کلائنٹ کو آزمائش بھیجیں۔</p>\n<h2 id=\"encoding-for-api-json\">API JSON پے لوڈ کے لیے تصویریں انکوڈ کرنا</h2>\n<p>JSON بائنری ڈیٹا نہیں رکھ سکتا، اس لیے JSON قبول کرنے والے تصویر اپ لوڈ اینڈ پوائنٹ تصویر کو Base64 اسٹرنگ کے طور پر توقع کرتے ہیں۔ Raw آؤٹ پٹ ٹیب آپ کو بالکل وہی شکل دیتا ہے۔</p>\n<p>کچی اسٹرنگ اس JSON خانے میں کاپی کریں جسے API دستاویز بتاتی ہے، اور اگر API مانگے تو میڈیا قسم الگ خانے میں بھیجیں۔ سرور اسٹرنگ ڈی کوڈ کرتا ہے اور فائل دوبارہ بناتا ہے۔</p>\n<p>پے لوڈ سائز پر نظر رکھیں۔ 1 MB تصویر 1.4 MB JSON خانہ بن جاتی ہے، اور کچھ API حد سے اوپر پے لوڈ مسترد کر دیتی ہیں۔ اگر API کی سائز حد ہو تو انکوڈ سے پہلے تصویر کمپریس کریں۔</p>\n<h2 id=\"shrinking-before-encoding\">انکوڈ کرنے سے پہلے تصویر چھوٹی کرنا</h2>\n<p>بڑی تصویر انکوڈ کرنے سے بہت لمبی اسٹرنگ بنتی ہے، اور لمبی اسٹرنگ کاپی کرنا مشکل، پڑھنا سست اور محفوظ کرنا بھاری ہوتا ہے۔ پہلے چھوٹا کرنا تقریباً ہمیشہ قابل قدر ہوتا ہے۔</p>\n<p>انکوڈ کرنے سے پہلے تصویر کو <a href=\"/\">Image Compressor</a> سے کمپریس کریں۔ 2 MB سے 200 KB تک کم کی گئی تصویر دس گنا چھوٹی اسٹرنگ بناتی ہے، کوالٹی نقصان کے ساتھ جو عام طور پر نظر نہیں آتا۔</p>\n<p>جب دکھائی دینے والا سائز چھوٹا ہو تو ری سائز بھی کریں۔ 64 پکسل پر دکھایا جانے والا آئیکن 2000 پکسل ماخذ نہیں مانگتا، اور چھوٹا ماخذ کہیں چھوٹی اسٹرنگ میں انکوڈ ہوتا ہے۔</p>\n<h2 id=\"troubleshooting-clipboard\">کلپ بورڈ کاپی مسائل کی خرابی دور کرنا</h2>\n<p>اگر کاپی بٹن کچھ نہ کرے تو آپ کے براؤزر نے کلپ بورڈ رسائی روکی ہو سکتی ہے۔ ٹول رکاوٹ بتانے والا پیغام دکھائے گا، اور آپ صفحے کے لیے اجازت دے سکتے ہیں۔</p>\n<p>کچھ براؤزر محفوظ صفحے پر صارف کے اشارے کے بعد ہی کلپ بورڈ لکھنے دیتے ہیں۔ بٹن پر کلک اشارہ شمار ہوتا ہے، مگر پرانا براؤزر یا سخت ترتیب پھر بھی انکار کر سکتا ہے۔</p>\n<p>ڈاؤن لوڈ بٹن قابل اعتماد متبادل ہے۔ یہ بالکل آؤٹ پٹ متن فائل کے طور پر محفوظ کرتا ہے، بغیر کلپ بورڈ کے، اور آپ فائل کھول کر وہاں سے کاپی کر سکتے ہیں۔</p>\n<h2 id=\"troubleshooting-large-strings\">بہت لمبی اسٹرنگ کی خرابی دور کرنا</h2>\n<p>بڑی تصویر کے لیے لمبی اسٹرنگ معمول ہے، مگر یہ آپ کے ایڈیٹر کو سست کر سکتی ہے۔ کوڈ فائل میں 2 MB اسٹرنگ پیسٹ کرنا ہلکے ایڈیٹر کو سیکنڈوں کے لیے جما سکتا ہے۔</p>\n<p>کام تقسیم کریں: اسٹرنگ الگ فائل یا متغیر میں محفوظ کریں، اور اسے اس کوڈ سے حوالہ دیں جسے اس کی ضرورت ہے۔ اس سے آپ کی اصل فائلیں پڑھنے کے قابل اور آپ کا ایڈیٹر جوابدہ رہتا ہے۔</p>\n<p>اگر اسٹرنگ آپ کی بلڈ توڑ دے تو لائن لمبائی حد جانچیں۔ کچھ اوزار بہت لمبی لائنوں کو لپیٹ یا کاٹ دیتے ہیں، جو اسٹرنگ خراب کر دیتا ہے۔ ڈاؤن لوڈ شدہ فائل اس مسئلے سے مکمل بچاتی ہے۔</p>\n<h2 id=\"encoding-another-image\">پہلی کے بعد دوسری تصویر انکوڈ کرنا</h2>\n<p>دوسری تصویر انکوڈ کرنے کے لیے صفحہ دوبارہ لوڈ کیے بغیر اسے ٹول سے اپ لوڈ کریں۔ نئی تصویر پرانی کی جگہ لیتی ہے، اور آؤٹ پٹ نئی اسٹرنگ پر اپ ڈیٹ ہو جاتا ہے۔</p>\n<p>بدلنے سے پہلے پہلا آؤٹ پٹ کاپی کریں، کیونکہ تصویر بدلنے سے پچھلی اسٹرنگ صاف ہو جاتی ہے۔ ڈاؤن لوڈ شدہ فائل محفوظ ترین ریکارڈ ہے اگر آپ کو دونوں اسٹرنگ چاہییں۔</p>\n<p>آئیکن کے سیٹ سے گزرنا اس طرح تیز ہے۔ اپ لوڈ کریں، کاپی کریں، اگلی اپ لوڈ کریں، دوبارہ کاپی کریں، اور پورا آئیکن سیٹ چند منٹ میں انکوڈ ہو جاتا ہے۔</p>\n<h2 id=\"encoding-for-social-and-messaging\">سوشل میڈیا اور پیغام رسانی کے لیے تصویریں انکوڈ کرنا</h2>\n<p>سوشل پوسٹ اور چیٹ پیغام کبھی تصویریں صرف متن کے طور پر قبول کرتے ہیں، خاص طور پر بوٹ، ویب ہک اور خودکار ورک فلو میں۔ Base64 اسٹرنگ تصویر کو صرف متن والے پیغام پے لوڈ کے اندر سفر کرنے دیتی ہے۔</p>\n<p>یہ تصویریں چھوٹی رکھیں۔ چیٹ API پیغام سائز چند درجن کلو بائٹ پر محدود کر سکتی ہے، اور Base64 میں انکوڈ شدہ تصویر پہنچنے سے پہلے ہی اس حد سے گزر جائے گی۔</p>\n<p>چیٹ بوٹ کے لیے 10 KB سے نیچے چھوٹا آئیکن یا تھمب نیل ایسی اسٹرنگ میں انکوڈ ہوتا ہے جو پیغام میں آرام سے فٹ ہوتی ہے۔ اس سے بڑی کوئی بھی چیز فائل کے طور پر اپ لوڈ کر کے URL سے حوالہ دینی چاہیے۔</p>\n<h2 id=\"quick-reference-checklist\">فوری حوالہ چیک لسٹ</h2>\n<p>تصویر اپ لوڈ کریں، اپنی منزل کے لیے آؤٹ پٹ ٹیب چنیں اور اسٹرنگ کاپی یا ڈاؤن لوڈ کریں۔ اس پر انحصار کرنے والی کوئی بھی چیز بھیجنے سے پہلے اسے اپنی جگہ پر آزمائیں۔</p>\n<p>انکوڈ سے پہلے بڑی تصویریں چھوٹی کریں، API کے لیے کچی Base64 استعمال کریں اور بڑی یا کئی صفحوں پر شیئر شدہ کسی بھی چیز کے لیے ایمبیڈ شدہ اسٹرنگ کی بجائے لنک شدہ فائل کو ترجیح دیں۔</p>\n<p>مکمل پس منظر کے لیے <a href=\"/ur/blog/tasveer-ko-base64-rehnumai/\">Image to Base64: Complete Guide</a> پڑھیں، اور فیصلہ فریم ورک کے لیے <a href=\"/ur/blog/base64-tasveer-kab-embed-karein/\">Base64 Images: When to Embed and When Not To</a> دیکھیں۔ اسٹرنگ کو واپس فائل میں ڈی کوڈ کرنے کے لیے <a href=\"/ur/base64-ko-tasveer-mein-convert-karein/\">Base64 to Image ڈی کوڈر</a> استعمال کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"کیا فون پر تصویر Base64 میں بدل سکتا ہوں؟","answer":"جی ہاں۔ کنورٹر آئی او ایس اور اینڈرائیڈ پر موبائل براؤزر میں چلتا ہے۔ گیلری سے تصویر اپ لوڈ کریں، آؤٹ پٹ ٹیب چنیں اور اسٹرنگ کاپی کریں۔ بہت لمبی اسٹرنگ کے لیے کاپی کرنے کی بجائے آؤٹ پٹ فائل ڈاؤن لوڈ کریں، کیونکہ موبائل کلپ بورڈ بڑے متن سے مشکل کر سکتے ہیں۔"},{"question":"HTML ٹیب تصویر ٹیگ میں چوڑائی اور اونچائی کیوں جوڑتا ہے؟","answer":"براؤزر کو تصویر ڈی کوڈ ہونے سے پہلے جگہ محفوظ کرنے کے لیے ابعاد چاہییں ہوتے ہیں۔ ان کے بغیر تصویر ظاہر ہونے پر صفحہ کا لے آؤٹ بدل جاتا ہے، جو پڑھنے کے تجربے اور لے آؤٹ شفٹ اسکور کو نقصان پہنچاتا ہے۔ ٹول یہ خاصیتیں تصویر کے ابعاد سے خود بخود بھر دیتا ہے۔"},{"question":"اپنی ویب سائٹ لوگو کے لیے Base64 استعمال کروں یا عام تصویر فائل؟","answer":"کئی صفحوں پر ظاہر ہونے والے لوگو کے لیے عام لنک شدہ فائل عام طور پر بہتر ہوتی ہے کیونکہ براؤزر اسے ایک بار کیش کرتا ہے۔ Base64 اس وقت جیتتا ہے جب صفحہ ایک فائل ہونا چاہیے، جب لوگو چھوٹا ہو یا جب الگ درخواست کی اجازت نہ ہو۔ زیادہ تر سائٹس کے لیے لوگو لنک کریں۔"},{"question":"Data URL اور کچی Base64 میں کیا فرق ہے؟","answer":"Data URL مکمل URI ہے، data پیش لاحقہ، میڈیا قسم اور انکوڈنگ نشان کے ساتھ، تصویر ماخذ کے طور پر استعمال کے لیے تیار۔ کچی Base64 صرف اسٹرنگ ہوتی ہے، بغیر پیش لاحقے کے، جو وہ شکل ہے جس کی API اور ڈیٹا بیس عام طور پر توقع کرتے ہیں۔ ٹول ایک ہی تصویر سے دونوں بناتا ہے۔"},{"question":"کیا Base64 میں بدلنے سے میری تصویر کا میٹا ڈیٹا ہٹ جاتا ہے؟","answer":"انکوڈنگ خود کچھ نہیں ہٹاتی، کیونکہ اسٹرنگ بالکل اصل بائٹ رکھتی ہے۔ البتہ، کچھ ورک فلو اسٹرنگ چھوٹی رکھنے کے لیے انکوڈ سے پہلے میٹا ڈیٹا ہٹا دیتے ہیں۔ اگر رازداری اہم ہو تو پہلے Remove Metadata ٹول سے میٹا ڈیٹا ہٹائیں، پھر صاف فائل انکوڈ کریں۔"},{"question":"کیا اسکرین شاٹ فائل محفوظ کیے بغیر سیدھا انکوڈ کر سکتا ہوں؟","answer":"جی ہاں۔ اسکرین شاٹ کاپی کریں اور ٹول میں Ctrl+V دبائیں، اور وہ فوراً انکوڈ ہو جائے گا۔ یہ اسکرین کیپچر، UI جز یا ڈایاگرام کے لیے Data URL لینے کا تیز ترین طریقہ ہے جسے آپ ابھی دیکھ رہے ہیں۔"}];
